#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Run from the repo root no matter where the script was invoked from. VARIANT
# is remembered across runs in firmware/.flash.env (gitignored).
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/firmware/.flash.env"

# Optional positional arg forces the variant: bin/flash.sh [clique|no-clique]
CLI_VARIANT="${1:-}"
if [[ -n "$CLI_VARIANT" && "$CLI_VARIANT" != "clique" && "$CLI_VARIANT" != "no-clique" ]]; then
  echo "usage: bin/flash.sh [clique|no-clique]" >&2
  exit 2
fi

# cp -X on macOS skips extended attributes, avoiding the spurious
# "could not copy extended attributes ... Device not configured" warning when
# writing to UF2 bootloader drives (FAT volumes).
COPY=(cp)
[[ "$(uname)" == "Darwin" ]] && COPY=(cp -X)

# Pin the fork explicitly for every gh call. Without -R / a literal repo,
# some gh commands resolve the upstream (KinesisCorporation) repo when the
# fork has an 'upstream' remote, and runs vanish (404s / empty listings).
FORK_REPO=$(git remote get-url origin | sed -E 's#^(git@github\.com:|https://github\.com/)##; s#\.git$##')

# Commit whose build we'll flash — HEAD normally, or @{u} if there are
# unpushed commits the user chose not to push (only pushed commits get builds).
FLASH_SHA=$(git rev-parse HEAD)
SHORT=$(git rev-parse --short HEAD)

# resolve_run_id — print the newest Actions run id for FLASH_SHA, or nothing.
# Goes through the REST API: `gh run list --commit` lags for very fresh runs
# (sometimes 60s+), which matters when the wizard runs right after a push.
resolve_run_id() {
  gh api "repos/$FORK_REPO/actions/runs?head_sha=$FLASH_SHA&per_page=1" \
    --jq 'if .workflow_runs | length > 0 then .workflow_runs[0].id else "" end' 2>/dev/null || true
}

# run_field <id> <jq-expr> — pull fields for a run: status, conclusion, url.
run_field() {
  gh run view "$1" --repo "$FORK_REPO" --json status,conclusion,url --jq "$2" 2>/dev/null || true
}

# wait_and_flash <uf2-file> — watch removable-drive roots for a UF2 bootloader
# drive (identified by INFO_UF2.TXT at its root), copy the file onto it, and
# confirm the drive ejects itself (the flash-complete signal). 10 min timeout.
wait_and_flash() {
  local file="$1" v j root deadline start last_note
  local roots=()
  [[ -d /Volumes ]] && roots+=(/Volumes)
  [[ -d "/media/$USER" ]] && roots+=("/media/$USER")
  [[ -d "/run/media/$USER" ]] && roots+=("/run/media/$USER")
  start=$SECONDS
  last_note=$SECONDS
  deadline=$((SECONDS + 600))
  while (( SECONDS < deadline )); do
    for root in "${roots[@]}"; do
      for v in "$root"/*/; do
        [[ -f "${v}INFO_UF2.TXT" ]] || continue
        printf '  %s✓ found%s bootloader drive %s\n' "$GREEN" "$RESET" "$v"
        if "${COPY[@]}" "$file" "$v"; then
          printf '  %s✓ copied%s %s → %s\n' "$GREEN" "$RESET" "$(basename "$file")" "$v"
        else
          warn "copy to $v failed — re-enter bootloader mode and retry"
          continue
        fi
        for j in $(seq 1 60); do
          if [[ ! -d "$v" ]]; then
            printf '  %s✓ drive ejected — flash complete%s\n' "$GREEN" "$RESET"
            return 0
          fi
          sleep 1
        done
        warn "drive still mounted after 60s — the copy itself usually worked"
        confirm "Did the drive eject / finish flashing?" && return 0
        return 1
      done
    done
    if (( SECONDS - last_note >= 15 )); then
      printf '  %s… still watching for the bootloader drive (%ds elapsed)%s\n' \
        "$DIM" $((SECONDS - start)) "$RESET"
      last_note=$SECONDS
    fi
    sleep 2
  done
  warn "timed out after 10 minutes waiting for a bootloader drive"
  return 1
}

# Intro — no gate: the run starts immediately; do each step as you read it.
_clear
printf '\n%s%s  Kinesis Advantage 360 Pro — firmware flash%s\n' "$BOLD" "$BLUE" "$RESET"
printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
say "Auto-copies each .uf2 the moment a bootloader drive appears."
say "Ctrl-C and re-run any time."

# ── Stage 1: preflight ─────────────────────────────────────────────────────
stage "Pre-flight — gh, git state"
command -v gh >/dev/null 2>&1 || { warn "gh not installed — run: brew install gh"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh not authenticated — run: gh auth login"; exit 1; }
say "Repo: $REPO_ROOT"
say "HEAD: $SHORT"

AHEAD=0
if git rev-parse --verify -q '@{u}' >/dev/null 2>&1; then
  AHEAD=$(git rev-list --count '@{u}..HEAD')
fi
if (( AHEAD > 0 )); then
  warn "$AHEAD unpushed commit(s) — the cloud build only triggers on push."
  if confirm "Push now?"; then
    git push
    say "Pushed. The build will appear in a few seconds."
  else
    FLASH_SHA=$(git rev-parse '@{u}')
    SHORT=$(git rev-parse --short "$FLASH_SHA")
    note "Continuing anyway — we'll flash the last pushed build ($SHORT), not HEAD."
  fi
fi

# ── Stage 2: locate and watch the build ────────────────────────────────────
stage "Cloud build — find & watch the run"
RUN_ID=""
for _ in $(seq 1 12); do
  RUN_ID=$(resolve_run_id)
  [[ -n "$RUN_ID" ]] && break
  sleep 5
done
if [[ -z "$RUN_ID" ]]; then
  warn "no GitHub Actions run found for commit $SHORT."
  step "Push your keymap change first (a build triggers on every push), then re-run."
  open_url "https://github.com/$FORK_REPO/actions"
  exit 1
fi
say "Found run $RUN_ID for $SHORT."

STATUS=$(run_field "$RUN_ID" '.status')
CONCLUSION=$(run_field "$RUN_ID" '.conclusion // ""')
if [[ "$STATUS" == "completed" && "$CONCLUSION" == "success" ]]; then
  say "Build already finished — success. Skipping the wait."
elif ! gh run watch "$RUN_ID" --repo "$FORK_REPO" --exit-status --interval 20; then
  warn "build failed for $SHORT."
  step "Fix the keymap error, push again (a new build triggers), then re-run this wizard."
  open_url "$(run_field "$RUN_ID" '.url')"
  exit 1
fi

# ── Stage 3: download artifacts, pick variant ──────────────────────────────
stage "Firmware — download & pick variant"
for ARTIFACT in firmware-clique firmware-no-clique; do
  rm -rf "firmware/$ARTIFACT"
  gh run download "$RUN_ID" --repo "$FORK_REPO" -n "$ARTIFACT" -D "firmware/$ARTIFACT" >/dev/null 2>&1 \
    || { warn "couldn't download artifact '$ARTIFACT' from run $RUN_ID"; exit 1; }
done
say "Both variants downloaded."

# Variant: CLI arg wins, then the remembered choice, then clique default.
if [[ -n "$CLI_VARIANT" ]]; then
  VARIANT="$CLI_VARIANT"
else
  VARIANT=$(_existing VARIANT || true)
  [[ -n "$VARIANT" ]] || VARIANT="clique"
fi
[[ "$(_existing VARIANT || true)" == "$VARIANT" ]] || write_env VARIANT "$VARIANT"
say "Variant: ${BOLD}$VARIANT${RESET} (clique = works with the Kinesis web editor)"
note "    switch with: bin/flash.sh no-clique"

LEFT_UF2=$(find "firmware/firmware-$VARIANT" -maxdepth 1 -name '*-left.uf2' 2>/dev/null | sort -r | head -1 || true)
RIGHT_UF2=$(find "firmware/firmware-$VARIANT" -maxdepth 1 -name '*-right.uf2' 2>/dev/null | sort -r | head -1 || true)
[[ -f "$LEFT_UF2" && -f "$RIGHT_UF2" ]] || { warn "uf2 files missing in firmware/firmware-$VARIANT/"; exit 1; }
say "Using:"
ls -lh "$LEFT_UF2" "$RIGHT_UF2" | awk '{print "    " $5 "  " $9}'

# ── Stage 4: flash left half ───────────────────────────────────────────────
stage "Flash LEFT half"
say "Key refresher — the inner columns, top to bottom:"
note "    LEFT half:   [kp]  [macro1] [macro2] [fn]"
note "    RIGHT half:  [Mod] [macro3] [macro4] [fn]"
note "    (macro1–4 are the four blank hotkeys; Mod is top-inner on the right)"
step "1. Switch BOTH halves on (Mod lives on the right half)."
step "2. Plug the LEFT half into USB."
step "3. Hold Mod + tap macro1 (upper blank hotkey, right next to T)."
note "    Fallback: double-tap the reset pinhole under the left module."
printf '\n  %s%s↻ watching for the ADV360PRO drive…%s\n\n' \
  "$BOLD" "$GREEN" "$RESET"
until wait_and_flash "$LEFT_UF2"; do
  confirm "Retry watching for the left half?" || exit 1
done
printf '  %s%s✓ LEFT half flashed%s\n' "$BOLD" "$GREEN" "$RESET"
sleep 2

# ── Stage 5: flash right half ──────────────────────────────────────────────
stage "Flash RIGHT half"
step "1. Unplug the left half."
step "2. Switch BOTH halves off."
step "3. Switch the LEFT half back on — leave it unplugged."
step "4. Plug the RIGHT half into USB (powers it on; halves re-link via left)."
step "5. Hold Mod + tap macro3 — the blank hotkey directly below Mod."
note "    Fallback: double-tap the reset pinhole under the right module."
printf '\n  %s%s↻ watching for the ADV360PRO drive…%s\n\n' \
  "$BOLD" "$GREEN" "$RESET"
until wait_and_flash "$RIGHT_UF2"; do
  confirm "Retry watching for the right half?" || exit 1
done
printf '  %s%s✓ RIGHT half flashed%s\n' "$BOLD" "$GREEN" "$RESET"
sleep 2

# ── Stage 6: final cycle & verify ──────────────────────────────────────────
stage "Done — power cycle & test"
printf '  %s%s✓ Both halves flashed: %s (%s)%s\n\n' "$BOLD" "$GREEN" "$SHORT" "$VARIANT" "$RESET"
step "1. Unplug the right half."
step "2. Switch both halves off, then back on."
step "3. Test your new keybinds."
note "    Optional: Mod+V types the build stamp — both halves should show"
note "    the commit $SHORT. A spurious macOS copy-error is normal if the"
note "    drive ejected afterwards."
printf '\n'
